func (s *Service) loadGrants(ctx context.Context, p *Principal) error {
	rows, err := s.pool.Query(ctx, `SELECT DISTINCT r.code,p.code
FROM ai_admin.user_role ur JOIN ai_admin.role r ON r.id=ur.role_id
LEFT JOIN ai_admin.role_permission rp ON rp.role_id=r.id
LEFT JOIN ai_admin.permission p ON p.code=rp.permission_code
WHERE ur.user_id=$1 ORDER BY r.code,p.code`, p.ID)
	if err != nil {
		return fmt.Errorf("load user permissions: %w", err)
	}
	defer rows.Close()
	roles, permissions := map[string]bool{}, map[string]bool{}
	for rows.Next() {
		var role string
		var permission *string
		if err := rows.Scan(&role, &permission); err != nil {
			return err
		}
		roles[role] = true
		if permission != nil {
			permissions[*permission] = true
		}
	}
	for role := range roles {
		p.Roles = append(p.Roles, role)
	}
	for permission := range permissions {
		p.Permissions = append(p.Permissions, permission)
	}
	return rows.Err()
}

func (s *Service) RevokeSession(ctx context.Context, hash string) error {
	if hash == "" {
		return nil
	}
	_, err := s.pool.Exec(ctx, `UPDATE ai_admin.session SET revoked_at=coalesce(revoked_at,now()) WHERE id_hash=$1`, hash)
	return err
	}
	if requester == p.ID {
		writeError(w, 409, "self_approval_denied", "본인의 요청은 직접 승인할 수 없습니다.")
		return
	}
	if !principalHasRole(p, approverRole) && !principalHasRole(p, "super_admin") {
		writeError(w, 403, "approver_role_required", "이 정책에 지정된 검토자 역할이 필요합니다.", map[string]string{"requiredRole": approverRole})
		return
	}
	if assignedTo != nil && *assignedTo != p.ID && !principalHasRole(p, "super_admin") {
		writeError(w, 403, "approval_assigned_to_other", "다른 검토자에게 지정된 요청입니다.")
		return
	}
	var alreadyReviewed bool
	if err := tx.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM ai_admin.approval_action WHERE request_id=$1 AND actor_id=$2)`, id, p.ID).Scan(&alreadyReviewed); err != nil {
		writeError(w, 500, "approval_failed", "승인 이력을 확인하지 못했습니다.")
		return
	}
	if alreadyReviewed {
		writeError(w, 409, "reviewer_already_acted", "다단계 승인은 단계마다 다른 검토자가 처리해야 합니다.")
		return
	}
	_, err = tx.Exec(r.Context(), `INSERT INTO ai_admin.approval_action(request_id,level,actor_id,action,comment) VALUES($1,$2,$3,$4,$5)`, id, level, p.ID, decision, nullString(strings.TrimSpace(request.Comment)))
	if err != nil {
		writeError(w, 500, "approval_failed", "승인 이력을 저장하지 못했습니다.")
		return
	}
	final := decision
	if decision == "approved" && level < levels {
		final = "pending"
		_, err = tx.Exec(r.Context(), `UPDATE ai_admin.approval_request SET current_level=current_level+1,assigned_to=NULL,decision_comment=$2,updated_at=now() WHERE id=$1`, id, request.Comment)
	} else {
		_, err = tx.Exec(r.Context(), `UPDATE ai_admin.approval_request SET status=$2,decision_comment=$3,decided_by=$4,decided_at=now(),updated_at=now() WHERE id=$1`, id, decision, request.Comment, p.ID)
	}
	if err != nil {
		writeError(w, 500, "approval_failed", "승인 요청을 저장하지 못했습니다.")
		return
	}
	if final == "approved" {
		var payload map[string]any
		_ = json.Unmarshal(payloadRaw, &payload)
		if err = s.executeApprovedOperation(r.Context(), tx, id, policy, payload, requestSecret, requester, p.ID); err != nil {
			problem := classifyApprovalExecutionError(err)
			writeError(w, problem.Status, problem.Code, problem.Message)
			return
		}
		_, err = tx.Exec(r.Context(), `UPDATE ai_admin.approval_request SET request_secret_ciphertext=NULL WHERE id=$1`, id)
		if err != nil {
			writeError(w, 500, "approval_execution_failed", "승인 요청의 비밀 데이터를 정리하지 못했습니다.")
			return
		}
	} else if final == "rejected" {
		_, err = tx.Exec(r.Context(), `UPDATE ai_admin.approval_request SET request_secret_ciphertext=NULL WHERE id=$1`, id)
		if err != nil {
			writeError(w, 500, "approval_failed", "반려된 요청의 비밀 데이터를 정리하지 못했습니다.")
			return
		}
	}
	if err = tx.Commit(r.Context()); err != nil {
		writeError(w, 500, "approval_failed", "승인 요청을 저장하지 못했습니다.")
		return
	}
	s.audit(r, p, "approval."+decision, "approval_request", id.String(), "success", map[string]any{"level": level, "finalStatus": final})
	writeData(w, 200, map[string]any{"id": id, "status": final, "currentLevel": level})
}

