	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// stubAuditRows replays a fixed result set so the export loop can be exercised
// without a database, including the two ways a real stream fails: a row that
// cannot be scanned and a stream that ends with an error.
type stubAuditRows struct {
	values   [][]any
	index    int
	scanErr  error
	scanFail int
	streamer error
}

func (rows *stubAuditRows) Close() {}

func (rows *stubAuditRows) Err() error { return rows.streamer }

func (rows *stubAuditRows) CommandTag() pgconn.CommandTag { return pgconn.CommandTag{} }

func (rows *stubAuditRows) FieldDescriptions() []pgconn.FieldDescription { return nil }

func (rows *stubAuditRows) Next() bool {
	if rows.index >= len(rows.values) {
		return false
	}
	rows.index++
	return true
}

func (rows *stubAuditRows) Scan(dest ...any) error {
	if rows.scanErr != nil && rows.index > rows.scanFail {
		return rows.scanErr
	}
	current := rows.values[rows.index-1]
	if len(current) != len(dest) {
		return fmt.Errorf("scan into %d destinations from %d values", len(dest), len(current))
	}
	for position, target := range dest {
		switch typed := target.(type) {
		case *int64:
			*typed = current[position].(int64)
		case *time.Time:
			*typed = current[position].(time.Time)
		case *string:
			*typed = current[position].(string)
		case *bool:
			*typed = current[position].(bool)
		case *uuid.UUID:
			*typed = current[position].(uuid.UUID)
		default:
			return fmt.Errorf("unsupported destination %T", target)
		}
	}
	return nil
}

func (rows *stubAuditRows) Values() ([]any, error) { return nil, nil }

func (rows *stubAuditRows) RawValues() [][]byte { return nil }

func (rows *stubAuditRows) Conn() *pgx.Conn { return nil }

func auditExportRow(id int64, action string) []any {
	return []any{id, time.Unix(0, 0).UTC(), "operator", "운영자", "user", action, "app_user", "row-1", "success", "10.0.0.1", "req-1", "", ""}
}

func TestStreamAuditCSVWritesEveryRow(t *testing.T) {
	buffer := &bytes.Buffer{}
	writer := csv.NewWriter(buffer)
	rows := &stubAuditRows{values: [][]any{auditExportRow(1, "settings.update"), auditExportRow(2, "=HYPERLINK(\"x\")")}}
	exported, failureReason := streamAuditCSV(writer, rows)
	writer.Flush()
	if exported != 2 || failureReason != "" {
		t.Fatalf("완료된 export가 실패로 보고되었습니다: rows=%d reason=%q", exported, failureReason)
	}
	if lines := strings.Count(strings.TrimSpace(buffer.String()), "\n") + 1; lines != 2 {
		t.Fatalf("행 수가 %d개입니다", lines)
	}
	if !strings.Contains(buffer.String(), `'=HYPERLINK`) {
		t.Fatalf("수식 셀이 중화되지 않았습니다: %q", buffer.String())
	}
}

func TestStreamAuditCSVReportsTruncation(t *testing.T) {
	for _, testCase := range []struct {
		name     string
		rows     *stubAuditRows
		exported int
		reason   string
	}{
		{
			name:     "row scan failure",
			rows:     &stubAuditRows{values: [][]any{auditExportRow(1, "a"), auditExportRow(2, "b")}, scanErr: errors.New("bad row"), scanFail: 1},
			exported: 1,
			reason:   "row_scan_failed",
		},
		{
			// 조회 제한 시간을 넘기면 pgx는 남은 행 없이 Err()만 남긴다.
			name:     "stream failure",
			rows:     &stubAuditRows{values: [][]any{auditExportRow(1, "a")}, streamer: errors.New("timeout")},
			exported: 1,
			reason:   "row_stream_failed",
		},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			writer := csv.NewWriter(&bytes.Buffer{})
			exported, failureReason := streamAuditCSV(writer, testCase.rows)
			if exported != testCase.exported || failureReason != testCase.reason {
				t.Fatalf("잘린 export가 rows=%d reason=%q로 보고되었습니다", exported, failureReason)
			}
		})
	}
}

func TestRecovererKeepsAbortAndAnswersOtherPanics(t *testing.T) {
	app := &Server{logger: slog.New(slog.NewTextHandler(io.Discard, nil))}
	aborting := app.recoverer(http.HandlerFunc(func(_ http.ResponseWriter, _ *http.Request) {
		panic(http.ErrAbortHandler)
	}))
	var recovered any
	func() {
		defer func() { recovered = recover() }()
		aborting.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/api/v1/audit/events/export", nil))
	}()
	if recovered != http.ErrAbortHandler {
		t.Fatalf("중단 신호가 recoverer에서 삼켜졌습니다: %v", recovered)
	}

	failing := app.recoverer(http.HandlerFunc(func(_ http.ResponseWriter, _ *http.Request) {
		panic("boom")
	}))
	recorder := httptest.NewRecorder()
	failing.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/api/v1/settings", nil))
	if recorder.Code != http.StatusInternalServerError || !strings.Contains(recorder.Body.String(), "internal_error") {
		t.Fatalf("일반 panic 응답이 %d %q입니다", recorder.Code, recorder.Body.String())
	}
}

func TestAccessLogRecordsAbortedRequests(t *testing.T) {
	logs := &bytes.Buffer{}
	app := &Server{logger: slog.New(slog.NewTextHandler(logs, nil))}
	handler := app.accessLog(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
		panic(http.ErrAbortHandler)
	}))
	func() {
		defer func() { _ = recover() }()
		handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, "/api/v1/audit/events/export", nil))
	}()
	if !strings.Contains(logs.String(), "/api/v1/audit/events/export") {
		t.Fatalf("중단된 요청이 접근 로그에 남지 않았습니다: %q", logs.String())
	}
}
