)

// Both the X-Request-Id and the User-Agent header are arbitrary caller input
// that ends up in a bounded PostgreSQL column. A value PostgreSQL refuses would
// otherwise drop the audit record of the request that sent it, or fail the
// login outright.
func TestHostileRequestHeadersDoNotBreakAuditingOrLogin(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()

	hostileRequestID := strings.Repeat("A", 4*requestIDMaximum) + "\xff"
	failed := loginRequest(t, handler, "wrong-password", hostileRequestID, "Mozilla/5.0")
	if failed.Code != http.StatusUnauthorized {
		t.Fatalf("failed login status=%d body=%s", failed.Code, failed.Body.String())
	}
	var requestID string
	if err := db.Pool.QueryRow(ctx, `SELECT coalesce(request_id,'') FROM ai_admin.audit_event
WHERE action='auth.login' AND result='failure' ORDER BY id DESC LIMIT 1`).Scan(&requestID); err != nil {
		t.Fatalf("the failed login left no audit record: %v", err)
	}
	if requestID == "" || !storableRequestID(requestID) || strings.HasPrefix(hostileRequestID, requestID) {
		t.Fatalf("audit record kept an unusable request id: %q", requestID)
	}

	// A long non-ASCII agent is cut at 1000 characters, not 1000 bytes, so the
	// stored value stays valid UTF-8 and fits varchar(1000) either way.
	hostileAgent := strings.Repeat("한", 900) + "\xff"
	succeeded := loginRequest(t, handler, "integration-password", "trace-0001", hostileAgent)
	if succeeded.Code != http.StatusOK {
		t.Fatalf("login with a hostile user agent status=%d body=%s", succeeded.Code, succeeded.Body.String())
	}
	var storedAgent string
	if err := db.Pool.QueryRow(ctx, `SELECT coalesce(user_agent,'') FROM ai_admin.session ORDER BY created_at DESC LIMIT 1`).Scan(&storedAgent); err != nil {
		t.Fatal(err)
	}
	if !utf8.ValidString(storedAgent) || utf8.RuneCountInString(storedAgent) != 900 {
		t.Fatalf("stored user agent is %d runes and valid=%v", utf8.RuneCountInString(storedAgent), utf8.ValidString(storedAgent))
	}
}

func loginRequest(t *testing.T, handler http.Handler, password, requestID, userAgent string) *httptest.ResponseRecorder {
	t.Helper()
	body, err := json.Marshal(map[string]any{"username": "admin@example.com", "password": password})
	if err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest(http.MethodPost, "/api/v1/auth/login", bytes.NewReader(body))
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-Request-Id", requestID)
	request.Header.Set("User-Agent", userAgent)
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)
	return recorder
}
