func TestEndToEndAPI(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}
	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Pool.Exec(ctx, `UPDATE ai_admin.key_scope SET assignable_by_user=true WHERE code=ANY($1)`, []string{"admin:read", "admin:write", "legacy:config"}); err != nil {
		t.Fatal(err)
	}
	protectedCount, protectedPrivilege, err := keyScopeState(ctx, db.Pool, []string{"legacy:config"})
	if err != nil || protectedCount != 1 || !protectedPrivilege {
		t.Fatalf("protected scope was downgraded by persisted metadata: count=%d privileged=%v err=%v", protectedCount, protectedPrivilege, err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	var repairedProtectedScopes int
	if err := db.Pool.QueryRow(ctx, `SELECT count(*) FROM ai_admin.key_scope
WHERE code=ANY($1) AND assignable_by_user`, []string{"admin:read", "admin:write", "legacy:config"}).Scan(&repairedProtectedScopes); err != nil || repairedProtectedScopes != 0 {
		t.Fatalf("seed did not repair protected key scopes: assignable=%d err=%v", repairedProtectedScopes, err)
	}
	if _, err := db.Pool.Exec(ctx, syntheticLegacySchema); err != nil {
		t.Fatal(err)
	}
	if _, err := db.Pool.Exec(ctx, `UPDATE ai_admin.app_user SET legacy_user_id='20000000-0000-4000-8000-000000000001' WHERE username='admin@example.com'`); err != nil {
