type dashboardMetric struct {
	Key       string `json:"key"`
	Label     string `json:"label"`
	Value     int64  `json:"value"`
	Available bool   `json:"available"`
}

func (s *Server) dashboard(w http.ResponseWriter, r *http.Request) {
	// 승인 대기 건수와 공급자 목록은 레거시 스키마가 아니라 ai_admin 자기 테이블에서
	// 온다. 여기서 실패한 조회를 0건·빈 목록으로 내리면 운영자는 처리할 승인이 없고
	// 등록된 공급자도 없다고 읽게 되므로, 없는 값과 구별할 수 있도록 요청을 실패시킨다.
	// 레거시 지표는 스키마가 없을 수 있어 available 플래그로 계속 degrade한다.
	var pending int64
	if err := s.db.Pool.QueryRow(r.Context(), `SELECT count(*) FROM ai_admin.approval_request WHERE status='pending'`).Scan(&pending); err != nil {
		writeError(w, http.StatusInternalServerError, "dashboard_unavailable", "대시보드 요약을 불러오지 못했습니다.")
		return
	}
	providers, err := s.dashboardProviders(r)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "dashboard_unavailable", "대시보드 요약을 불러오지 못했습니다.")
		return
	}
	schema := s.legacySchema(r)
	p := principalFrom(r.Context())
	metrics := []struct{ key, label, table string }{
		{"apps", "전체 앱", "app_info"},
		{"users", "전체 사용자", "user_info"},
		{"questions", "누적 질문", "question_log"},
		{"feedback", "피드백", "app_feedback"},
	}
	result := make([]dashboardMetric, 0, len(metrics))
	metricValues := make(map[string]int64, len(metrics))
	for _, metric := range metrics {
		count, available := s.tableCount(r, schema, metric.table)
		metricValues[metric.key] = count
		result = append(result, dashboardMetric{Key: metric.key, Label: metric.label, Value: count, Available: available})
	}
	maskSensitive := !p.HasPermission("legacy.sensitive.read")
	recent := s.recentActivity(r, schema, maskSensitive)
	if !maskSensitive && len(recent) > 0 {
		s.audit(r, p, "legacy.sensitive.read", "dashboard_activity", "recent", "success", map[string]any{"table": "activity_log", "rows": len(recent)})
	}
	users := metricValues["users"]
	questions := metricValues["questions"]
	tokens := s.legacyTokenTotal(r, schema)
	activities := make([]map[string]any, 0, len(recent))
	for _, item := range recent {
		activities = append(activities, map[string]any{"id": item["id"], "actor": item["userId"], "action": item["operation"], "target": item["result"], "createdAt": item["occurredAt"]})
	}
	writeData(w, http.StatusOK, map[string]any{
		"stats":        map[string]any{"activeUsers": users, "aiRequests": questions, "tokenUsage": tokens, "pendingApprovals": pending},
		"requestTrend": s.legacyRequestTrend(r, schema), "providerHealth": providers, "recentActivities": activities,
		"metrics": result, "recentActivity": recent, "legacySchema": schema, "generatedAt": time.Now().UTC(),
	})
}

func (s *Server) legacyTokenTotal(r *http.Request, schema string) int64 {
	if !s.tableExists(r, schema, "daily_stats") {
		return 0
	}
	var total int64
	query := `SELECT coalesce(sum(token_cnt),0)::bigint FROM ` + pgx.Identifier{schema, "daily_stats"}.Sanitize()
	queryContext, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	_ = s.db.Pool.QueryRow(queryContext, query).Scan(&total)
	return total
}

func (s *Server) legacyRequestTrend(r *http.Request, schema string) []map[string]any {
	if !s.tableExists(r, schema, "daily_stats") {
		return []map[string]any{}
	}
	query := `SELECT base_date,coalesce(sum(question_cnt),0)::bigint FROM ` + pgx.Identifier{schema, "daily_stats"}.Sanitize() + ` GROUP BY base_date ORDER BY base_date DESC LIMIT 7`
	queryContext, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	rows, err := s.db.Pool.Query(queryContext, query)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	items := make([]map[string]any, 0)
	for rows.Next() {
		var label string
		var value int64
		if rows.Scan(&label, &value) == nil {
			items = append([]map[string]any{{"label": label, "value": value}}, items...)
		}
	}
	return items
}

