// The user directory search shares the 200-character contract of the audit,
// legacy and MCP searches: anything longer is refused before it reaches the
// three-column ILIKE scan. The limit counts characters, not bytes, because the
// SPA sends Korean search terms.
func TestListUsersRejectsOverlongQuery(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN is not set")
	}

	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Pool.Exec(ctx, `DROP SCHEMA IF EXISTS ai_admin CASCADE; DROP SCHEMA IF EXISTS aiportal CASCADE`); err != nil {
		t.Fatal(err)
	}
	if err := db.Migrate(ctx); err != nil {
		t.Fatal(err)
	}
	if err := db.Seed(ctx, "admin@example.com", "integration-password"); err != nil {
		t.Fatal(err)
	}
	cipher, err := secrets.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	handler := New(db, cipher, slog.New(slog.NewTextHandler(io.Discard, nil))).Handler()
	admin := signIn(t, handler)

	// Hangul is three bytes per character: a byte-based limit would wrongly
	// refuse these terms. display_name is varchar(190), so the longest name
	// that can exist is searched with itself and the 200-character term must
	// still reach the database and come back as an empty page.
	longestName := strings.Repeat("가", 190)
	exactLimit := strings.Repeat("가", 200)
	if _, err := db.Pool.Exec(ctx, `INSERT INTO ai_admin.app_user(id,username,display_name,auth_source,status)
VALUES($1,'long-name@example.com',$2,'local','active')`, uuid.New(), longestName); err != nil {
		t.Fatal(err)
	}
	list := func(q string) *http.Response {
		t.Helper()
		return admin.do(t, handler, http.MethodGet, "/api/v1/users?page=1&pageSize=25&q="+url.QueryEscape(q), nil).Result()
	}

	response := list(longestName)
	if response.StatusCode != http.StatusOK {
		t.Fatalf("190-character query status=%d body=%s", response.StatusCode, readBody(response))
	}
	var envelope legacyHTTPPage
	decodeResponse(t, response, &envelope)
	if envelope.Page.Total != 1 || len(envelope.Data) != 1 || envelope.Data[0]["username"] != "long-name@example.com" {
		t.Fatalf("190-character query did not return the matching user: %#v", envelope)
	}
	response = list(exactLimit)
	if response.StatusCode != http.StatusOK {
		t.Fatalf("200-character query status=%d body=%s", response.StatusCode, readBody(response))
	}
	decodeResponse(t, response, &envelope)
	if envelope.Page.Total != 0 || len(envelope.Data) != 0 {
		t.Fatalf("200-character query should have searched and found nobody: %#v", envelope)
	}

	overlong := list(exactLimit + "가")
	if overlong.StatusCode != http.StatusBadRequest {
		t.Fatalf("201-character query status=%d body=%s", overlong.StatusCode, readBody(overlong))
	}
	var failure struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	decodeResponse(t, overlong, &failure)
	if failure.Error.Code != "query_too_long" || failure.Error.Message != "검색어는 200자 이하여야 합니다." {
		t.Fatalf("201-character query error=%+v", failure.Error)
	}

	// Surrounding whitespace is trimmed before the limit is applied, and an
	// empty or absent q still lists everyone.
	padded := list("   " + exactLimit + "   ")
	if padded.StatusCode != http.StatusOK {
		t.Fatalf("padded 200-character query status=%d body=%s", padded.StatusCode, readBody(padded))
	}
	all := list("")
	if all.StatusCode != http.StatusOK {
		t.Fatalf("empty query status=%d body=%s", all.StatusCode, readBody(all))
	}
	decodeResponse(t, all, &envelope)
	if envelope.Page.Total != 2 {
		t.Fatalf("empty query total=%d want=2", envelope.Page.Total)
	}
}
