      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262 # v4.4.0
      - name: Validate referenced screenshots
        shell: bash
        run: |
          python3 - <<'PY'
          from html.parser import HTMLParser
          from pathlib import Path, PurePosixPath
          import re

          class ScreenshotReferences(HTMLParser):
              def __init__(self):
                  super().__init__()
                  self.paths = []

              def handle_starttag(self, tag, attrs):
                  if tag != "object":
                      return
                  attributes = dict(attrs)
                  data = attributes.get("data", "")
                  if data.startswith("screenshots/") and data.endswith(".webp"):
                      self.paths.append(data)

          parser = ScreenshotReferences()
          parser.feed(Path("docs/index.html").read_text(encoding="utf-8"))
          if len(parser.paths) != 44 or len(set(parser.paths)) != 44:
              raise SystemExit(
                  f"docs/index.html must reference 44 unique WebP screenshots; "
                  f"found {len(parser.paths)} references and {len(set(parser.paths))} unique paths"
              )

          referenced = set(parser.paths)
          actual = {
              f"screenshots/{path.name}"
              for path in Path("docs/screenshots").glob("*.webp")
          }
          if actual != referenced:
              raise SystemExit(
                  "docs/screenshots WebP set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - actual)}, extra={sorted(actual - referenced)}"
              )

          readme = Path("docs/screenshots/README.md").read_text(encoding="utf-8")
          documented = {
              f"screenshots/{name}"
              for name in re.findall(r"^\| `([^`]+\.webp)` \|", readme, flags=re.MULTILINE)
          }
          if documented != referenced:
              raise SystemExit(
                  "docs/screenshots/README.md set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - documented)}, extra={sorted(documented - referenced)}"
              )

          capture_source = Path("scripts/capture-screenshots.mjs").read_text(encoding="utf-8")
          captured = {"screenshots/login.webp", "screenshots/mobile.webp"} | {
              f"screenshots/{name}"
              for name in re.findall(r"\{ file: '([^']+\.webp)'", capture_source)
          }
          if captured != referenced:
              raise SystemExit(
                  "capture script set must exactly match docs/index.html; "
                  f"missing={sorted(referenced - captured)}, extra={sorted(captured - referenced)}"
              )

          for relative in parser.paths:
              path_parts = PurePosixPath(relative).parts
              if len(path_parts) != 2 or path_parts[0] != "screenshots":
                  raise SystemExit(f"Unsafe screenshot path in docs/index.html: {relative}")
              path = Path("docs") / relative
              if not path.is_file() or path.stat().st_size < 12:
                  raise SystemExit(f"Missing or empty screenshot: {path}")
              with path.open("rb") as screenshot:
                  header = screenshot.read(12)
              if header[:4] != b"RIFF" or header[8:12] != b"WEBP":
                  raise SystemExit(f"Invalid RIFF/WEBP signature: {path}")

          print("Validated exact 44-file screenshot set across index, directory, README, and capture script")
          PY
