func signIn(t *testing.T, handler http.Handler) sessionCredentials {
	t.Helper()
	login := loginRequest(t, handler, "integration-password", "trace-db-error", "Go-Test")
	if login.Code != http.StatusOK {
		t.Fatalf("login status=%d body=%s", login.Code, login.Body.String())
	}
	credentials := sessionCredentials{cookies: login.Result().Cookies()}
	for _, cookie := range credentials.cookies {
		if cookie.Name == "ai_admin_csrf" {
			credentials.csrf = cookie.Value
		}
	}
	if credentials.csrf == "" {
		t.Fatal("login did not issue a CSRF cookie")
	}
	return credentials
}

func (c sessionCredentials) do(t *testing.T, handler http.Handler, method, target string, body any) *httptest.ResponseRecorder {
	t.Helper()
	var reader io.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatal(err)
		}
		reader = bytes.NewReader(raw)
	}
	request := httptest.NewRequest(method, target, reader)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("X-CSRF-Token", c.csrf)
	for _, cookie := range c.cookies {
		request.AddCookie(cookie)
	}
	recorder := httptest.NewRecorder()
	handler.ServeHTTP(recorder, request)
	return recorder
}

// withRenamedTable makes every query against one ai_admin table fail the way a
// dropped or unreachable relation would, without touching the tables the
// session authentication itself needs.
func withRenamedTable(t *testing.T, db *database.DB, table string, run func()) {
	t.Helper()
	ctx := context.Background()
	if _, err := db.Pool.Exec(ctx, `ALTER TABLE ai_admin.`+table+` RENAME TO `+table+`_hidden`); err != nil {
		t.Fatal(err)
	}
	s.logger.Warn("authentication backend failure", "error", err, "path", r.URL.Path)
	w.Header().Set("Retry-After", "1")
	writeError(w, http.StatusServiceUnavailable, "auth_unavailable", "인증 정보를 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.")
}

func (s *Server) mcpAuthenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !validOrigin(r) {
			writeError(w, http.StatusForbidden, "origin_denied", "허용되지 않은 Origin입니다.")
			return
		}
		principal, err := s.auth.Authenticate(r)
		if err != nil {
			if errors.Is(err, auth.ErrUnauthenticated) {
				w.Header().Set("WWW-Authenticate", `Bearer realm="ai-admin-mcp"`)
			}
			s.writeAuthFailure(w, r, err, "mcp:tools scope가 있는 API 키가 필요합니다.")
			return
		}
		if principal.AuthMethod == "api_key" && !principal.HasScope("mcp:tools") {
			w.Header().Set("WWW-Authenticate", `Bearer realm="ai-admin-mcp"`)
			writeError(w, http.StatusUnauthorized, "unauthenticated", "mcp:tools scope가 있는 API 키가 필요합니다.")
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), principalKey{}, principal)))
	})
}
