package config

import (
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"strings"
)

const ListenAddress = ":8080"

type Config struct {
	PostgresDSN       string
	BootstrapAdmin    string
	BootstrapPassword string
	EncryptionKey     []byte
	ListenAddress     string
}

func Load() (Config, error) {
	cfg := Config{
		PostgresDSN:       strings.TrimSpace(os.Getenv("POSTGRES_DSN")),
		BootstrapAdmin:    strings.TrimSpace(os.Getenv("BOOTSTRAP_ADMIN")),
		BootstrapPassword: os.Getenv("BOOTSTRAP_ADMIN_PASSWORD"),
		ListenAddress:     ListenAddress,
	}

	missing := make([]string, 0, 4)
	if cfg.PostgresDSN == "" {
		missing = append(missing, "POSTGRES_DSN")
	}
	if cfg.BootstrapAdmin == "" {
		missing = append(missing, "BOOTSTRAP_ADMIN")
	}
	if cfg.BootstrapPassword == "" {
		missing = append(missing, "BOOTSTRAP_ADMIN_PASSWORD")
	}
	keyValue := strings.TrimSpace(os.Getenv("ENCRYPTION_KEY"))
	if keyValue == "" {
		missing = append(missing, "ENCRYPTION_KEY")
	}
	if len(missing) > 0 {
		return Config{}, fmt.Errorf("required environment variables are missing: %s", strings.Join(missing, ", "))
	}
	if len(cfg.BootstrapPassword) < 12 {
		return Config{}, errors.New("BOOTSTRAP_ADMIN_PASSWORD must contain at least 12 characters")
	}

	decoded, err := base64.StdEncoding.DecodeString(keyValue)
	if err != nil {
		decoded, err = base64.RawStdEncoding.DecodeString(keyValue)
	}
	if err != nil || len(decoded) != 32 {
		return Config{}, errors.New("ENCRYPTION_KEY must be exactly 32 random bytes encoded as base64")
	}
	cfg.EncryptionKey = decoded
	return cfg, nil
}
